description:
Two pieces of GDI painting:

```cpp
using COLORREF = std::uint32_t;
struct RECT { long left, top, right, bottom; };

COLORREF rgb(int r, int g, int b);                  // like the RGB macro: 0x00BBGGRR
int getR(COLORREF c); int getG(COLORREF c); int getB(COLORREF c);
bool fromHtml(const std::string& html, COLORREF& out);   // "#RRGGBB" or "#RGB", hex in either case
std::string toHtml(COLORREF c);                     // "#rrggbb" in lower case

bool isEmpty(RECT r);                               // no area
bool intersect(RECT a, RECT b, RECT& out);          // false (and out empty {0,0,0,0}) if they do not overlap
RECT unite(RECT a, RECT b);                         // bounding rectangle; an empty rectangle is ignored

class InvalidArea
{
public:
    void invalidate(RECT r);    // empty rectangles do nothing
    bool needsPaint() const;
    RECT bounds() const;        // {0,0,0,0} when nothing is invalid
    void validate();            // what EndPaint does
};
```

`#RGB` doubles each digit: `#f80` is `#ff8800`. Anything else (missing `#`, wrong length, a non-hex digit) is rejected.

