solution.solution.cpp:
#include <algorithm>
#include <cctype>
#include <cstdint>
#include <cstdio>
#include <string>

using COLORREF = std::uint32_t;
struct RECT { long left, top, right, bottom; };

COLORREF rgb(int r, int g, int b)
{
    return static_cast<COLORREF>((r & 0xFF) | ((g & 0xFF) << 8) | ((b & 0xFF) << 16));
}
int getR(COLORREF c) { return static_cast<int>(c & 0xFF); }
int getG(COLORREF c) { return static_cast<int>((c >> 8) & 0xFF); }
int getB(COLORREF c) { return static_cast<int>((c >> 16) & 0xFF); }

bool fromHtml(const std::string& html, COLORREF& out)
{
    if (html.empty() || html[0] != '#') return false;
    std::string digits{ html.substr(1) };
    for (char c : digits) if (!std::isxdigit(static_cast<unsigned char>(c))) return false;
    if (digits.size() == 3) digits = { digits[0], digits[0], digits[1], digits[1], digits[2], digits[2] };
    if (digits.size() != 6) return false;
    const unsigned long v{ std::stoul(digits, nullptr, 16) };
    out = rgb(static_cast<int>((v >> 16) & 0xFF), static_cast<int>((v >> 8) & 0xFF), static_cast<int>(v & 0xFF));
    return true;
}

std::string toHtml(COLORREF c)
{
    char buffer[8];
    std::snprintf(buffer, sizeof(buffer), "#%02x%02x%02x", getR(c), getG(c), getB(c));
    return buffer;
}

bool isEmpty(RECT r) { return r.right <= r.left || r.bottom <= r.top; }

bool intersect(RECT a, RECT b, RECT& out)
{
    const RECT r{ std::max(a.left, b.left), std::max(a.top, b.top), std::min(a.right, b.right), std::min(a.bottom, b.bottom) };
    if (isEmpty(r)) { out = { 0, 0, 0, 0 }; return false; }
    out = r;
    return true;
}

RECT unite(RECT a, RECT b)
{
    if (isEmpty(a)) return isEmpty(b) ? RECT{ 0, 0, 0, 0 } : b;
    if (isEmpty(b)) return a;
    return { std::min(a.left, b.left), std::min(a.top, b.top), std::max(a.right, b.right), std::max(a.bottom, b.bottom) };
}

class InvalidArea
{
public:
    void invalidate(RECT r) { if (!isEmpty(r)) m_bounds = unite(m_bounds, r); }
    bool needsPaint() const { return !isEmpty(m_bounds); }
    RECT bounds() const { return m_bounds; }
    void validate() { m_bounds = { 0, 0, 0, 0 }; }

private:
    RECT m_bounds{ 0, 0, 0, 0 };
};

unitTests:
bool same(RECT r, long l, long t, long rr, long b) { return r.left == l && r.top == t && r.right == rr && r.bottom == b; }
TEST("RGB order") { CHECK_EQ(rgb(0x12, 0x34, 0x56), COLORREF{ 0x00563412 }); CHECK_EQ(getR(0x00563412), 0x12); CHECK_EQ(getB(0x00563412), 0x56); }
TEST("HTML colours") {
    COLORREF c = 0; CHECK(fromHtml("#FF8800", c)); CHECK_EQ(c, COLORREF{ 0x000088FF }); CHECK_EQ(toHtml(c), std::string("#ff8800"));
    CHECK(fromHtml("#f80", c)); CHECK_EQ(c, COLORREF{ 0x000088FF }); CHECK(fromHtml("#0a0B0c", c)); CHECK_EQ(toHtml(c), std::string("#0a0b0c"));
    CHECK(!fromHtml("FF8800", c)); CHECK(!fromHtml("#FF880", c)); CHECK(!fromHtml("#GG8800", c)); CHECK(!fromHtml("#", c));
}
TEST("rectangles") {
    RECT o{}; CHECK(intersect({ 0, 0, 10, 10 }, { 5, 5, 20, 20 }, o)); CHECK(same(o, 5, 5, 10, 10));
    CHECK(!intersect({ 0, 0, 10, 10 }, { 10, 0, 20, 10 }, o)); CHECK(same(o, 0, 0, 0, 0));
    CHECK(same(unite({ 0, 0, 10, 10 }, { 20, 5, 30, 8 }), 0, 0, 30, 10)); CHECK(same(unite({ 5, 5, 5, 9 }, { 1, 2, 3, 4 }), 1, 2, 3, 4));
    CHECK(isEmpty({ 3, 3, 3, 10 })); CHECK(!isEmpty({ 0, 0, 1, 1 }));
}
TEST("invalid area") {
    InvalidArea a; CHECK(!a.needsPaint()); a.invalidate({ 10, 10, 20, 20 }); a.invalidate({ 50, 0, 60, 5 }); a.invalidate({ 0, 0, 0, 100 });
    CHECK(a.needsPaint()); CHECK(same(a.bounds(), 10, 0, 60, 20)); a.validate(); CHECK(!a.needsPaint()); CHECK(same(a.bounds(), 0, 0, 0, 0));
}

